export const combineState = reducers => {
  const globalState = {};

  // set default state returned by reducer and its reducer
  for (const [key, value] of Object.entries(reducers)) {

    if (typeof value === "function") {
      globalState[key] = value(undefined, { type: "rubbish" });
    } else {
      console.error(`${value} is not a function`);
    }
  }
  // return the initial state and the global reducer
  return [globalState];
};


export const combineReducers = (initialState, reducers) => 
  (state: any = initialState, action: any): any => {
    for(let i=0;i<reducers.length;i++) 
      state = reducers[i](state, action)
    return state;
  }
